import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("vendor names are unique within a tenant", () => {
  test("creating a vendor whose name matches an existing one in the tenant returns 409 vendor_name_taken", { tag: "@VEN-03" }, async ({ apiAs }) => {
    // Arrange: an existing vendor in the member's tenant
    const member = await apiAs("member");
    const base = uniqueName("Acme Freight");
    const existing = await member.post("/api/vendors", {
      data: { name: base, category: "logistics", contact_email: "ops@acmefreight.example" },
    });
    await expectStatus(existing, 201);

    // Act: create a vendor whose name differs only in letter case
    const response = await member.post("/api/vendors", {
      data: { name: base.toLowerCase(), category: "logistics", contact_email: "ops@acmefreight.example" },
    });

    // Assert
    const body = await expectStatus(response, 409);
    expect(body.error.code).toBe("vendor_name_taken");
  });

  test("a rejected duplicate is not persisted", { tag: "@VEN-03" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const base = uniqueName("Acme Freight");
    await expectStatus(
      await member.post("/api/vendors", {
        data: { name: base, category: "logistics", contact_email: "ops@acmefreight.example" },
      }),
      201,
    );

    // Act
    await member.post("/api/vendors", {
      data: { name: base.toLowerCase(), category: "logistics", contact_email: "ops@acmefreight.example" },
    });

    // Assert: only the original record matches the name in the tenant
    const page = await expectStatus(await member.get("/api/vendors", { params: { q: base } }), 200);
    const matches = page.items.filter((v: { name: string }) => v.name.toLowerCase() === base.toLowerCase());
    expect(matches).toHaveLength(1);
    expect(matches[0].name).toBe(base);
  });
});
